777: function explosionDamage(pos, radius, maxDamage, selfFactor = 0.5) {
778:   for (const e of enemies) {
779:     if (e.dead || e.spawnT > 0.2) continue;
780:     const d = e.root.position.distanceTo(pos);
781:     if (d < radius) {
782:       const dmg = maxDamage * (1 - d / radius) + 15;
783:       e.hit(dmg, 'body', e.root.position.clone().add(new THREE.Vector3(0, 1.2, 0)));
784:     }
785:   }
786:   for (const b of world.explosives) {
787:     if (b.exploded) continue;
788:     if (b.position.distanceTo(pos) < radius * 0.75) {
789:       setTimeout(() => { if (!b.exploded) explodeBarrel(b); }, 140 + Math.random() * 120);
790:     }
791:   }
792:   const pd = Math.hypot(player.pos.x - pos.x, player.pos.z - pos.z);
793:   if (pd < radius && !player.dead) damagePlayer(maxDamage * selfFactor * (1 - pd / radius), pos, false);
794: }
