822: function updateGrenades(dt) {
823:   for (let i = grenades.length - 1; i >= 0; i--) {
824:     const g = grenades[i];
825:     g.fuse -= dt;
826:     g.vel.y -= 18 * dt;
827:     const nextX = g.mesh.position.x + g.vel.x * dt;
828:     const nextZ = g.mesh.position.z + g.vel.z * dt;
829:     if (blockedAt(nextX, g.mesh.position.z, 0.14)) g.vel.x *= -0.55;
830:     else g.mesh.position.x = nextX;
831:     if (blockedAt(g.mesh.position.x, nextZ, 0.14)) g.vel.z *= -0.55;
832:     else g.mesh.position.z = nextZ;
833:     g.mesh.position.y += g.vel.y * dt;
834:     if (g.mesh.position.y < 0.14) {
835:       g.mesh.position.y = 0.14;
836:       g.vel.y *= -0.55;
837:       g.vel.x *= 0.85; g.vel.z *= 0.85;
838:       if (Math.abs(g.vel.y) < 0.5) g.vel.y = 0;
839:     }
840:     g.mesh.rotation.x += dt * 8;
841:     g.mesh.rotation.z += dt * 5;
842:     if (g.fuse <= 0) {
843:       const pos = g.mesh.position.clone();
844:       scene.remove(g.mesh);
845:       g.mesh.geometry.dispose();
846:       g.mesh.material.dispose();
847:       grenades.splice(i, 1);
848:       effects.explosion(pos, 8);
849:       audio.explosion();
850:       player.shake = Math.max(player.shake, 0.7);
851:       explosionDamage(pos, 8.5, 150, 0.42);
852:     }
853:   }
