916:   const w = dom.compass.width, h = dom.compass.height;
917:   ctx.clearRect(0, 0, w, h);
918:   const heading = ((-player.yaw * 180 / Math.PI) % 360 + 360) % 360;
919:   ctx.save();
920:   ctx.translate(w / 2, h - 12);
921:   ctx.font = '600 13px monospace';
922:   ctx.textAlign = 'center';
923:   const span = 70;
924:   for (let d = -span; d <= span; d += 5) {
925:     const deg = (heading + d + 360) % 360;
926:     const x = (d / span) * (w / 2 - 8);
927:     const major = deg % 45 === 0;
928:     const centerFade = 1 - Math.abs(d) / span;
929:     ctx.globalAlpha = 0.18 + centerFade * 0.72;
930:     ctx.strokeStyle = major ? '#ff8b3d' : 'rgba(230,242,245,0.55)';
931:     ctx.lineWidth = major ? 1.4 : 1;
932:     ctx.beginPath();
933:     ctx.moveTo(x, 0);
934:     ctx.lineTo(x, major ? -11 : -6);
935:     ctx.stroke();
936:     if (major) {
937:       const labels = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' };
938:       ctx.fillStyle = deg === 0 ? '#ff8b3d' : 'rgba(232,244,247,0.8)';
939:       ctx.fillText(labels[deg] || String(deg), x, -18);
940:     }
941:   }
942:   ctx.restore();
943:   // center chevron
944:   ctx.fillStyle = '#ff6a1a';
945:   ctx.beginPath();
946:   ctx.moveTo(w / 2, 2);
947:   ctx.lineTo(w / 2 - 5, 10);
948:   ctx.lineTo(w / 2 + 5, 10);
949:   ctx.closePath();
950:   ctx.fill();
