694: function updateWeapon(dt) {
695:   const w = currentWeapon();
696:   if (state.mode !== 'playing') {
697:     weaponRig.visible = false;
698:     return;
699:   }
700:   weaponRig.visible = true;
701:   const model = currentModel();
702:   if (weaponState.switchT > 0) weaponState.switchT -= dt;
703:   if (weaponState.flashT > 0) {
704:     weaponState.flashT -= dt;
705:     if (weaponState.flashT <= 0) {
706:       model.userData.muzzleFlash.visible = false;
707:       model.userData.flashLight.intensity = 0;
708:     }
709:   }
710: 
711:   if (weaponState.reloading) {
712:     weaponState.reloadT -= dt;
713:     if (weaponState.reloadT <= 0) finishReload();
714:   }
715: 
716:   const wantAds = weaponState.mouse2 && !weaponState.reloading && !player.sprinting;
717:   weaponState.ads = wantAds;
718:   weaponState.adsT = lerp(weaponState.adsT, wantAds ? 1 : 0, Math.min(1, dt * 12));
719: 
720:   const moveSpeed = Math.hypot(player.vel.x, player.vel.z);
721:   const bobScale = player.onGround ? Math.min(1, moveSpeed / 6) : 0.2;
722:   const bob = state.time * (player.sprinting ? 13 : 9.5);
723:   const bobX = Math.sin(bob) * 0.008 * bobScale * (1 - weaponState.adsT * 0.7);
724:   const bobY = Math.abs(Math.cos(bob)) * 0.006 * bobScale * (1 - weaponState.adsT * 0.7);
725: 
726:   weaponState.recoilKick = Math.max(0, weaponState.recoilKick - dt * 2.2);
727:   weaponState.recoilYaw = lerp(weaponState.recoilYaw, 0, Math.min(1, dt * 12));
728:   weaponState.swayX = lerp(weaponState.swayX, 0, Math.min(1, dt * 7));
729:   weaponState.swayY = lerp(weaponState.swayY, 0, Math.min(1, dt * 7));
730: 
731:   const base = weaponBase[weaponState.current];
732:   const ads = weaponAds[weaponState.current];
733:   const target = _v.copy(base).lerp(ads, weaponState.adsT);
734:   const reloadDip = weaponState.reloading ? Math.sin(Math.min(1, 1 - weaponState.reloadT / w.reloadTime) * Math.PI) : 0;
735:   target.x += bobX + weaponState.swayX;
736:   target.y += bobY + weaponState.swayY - reloadDip * 0.16 - weaponState.recoilKick * 0.014;
737:   target.z += weaponState.recoilKick * 0.16;
738:   weaponRig.position.lerp(target, Math.min(1, dt * 16));
739:   weaponRig.rotation.x = lerp(weaponRig.rotation.x, 0.015 + weaponState.recoilKick * 0.8 + reloadDip * 0.55, Math.min(1, dt * 14));
740:   const baseYaw = lerp(0.34, 0.0, weaponState.adsT);
741:   weaponRig.rotation.y = lerp(weaponRig.rotation.y, baseYaw + weaponState.recoilYaw + weaponState.swayX * 1.2 - reloadDip * 0.12, Math.min(1, dt * 14));
742:   weaponRig.rotation.z = lerp(weaponRig.rotation.z, 0.012 + reloadDip * 0.5 + bobX * 0.9, Math.min(1, dt * 14));
743: 
744:   const fov = weaponState.adsT > 0.02 ? lerp(74, 54, weaponState.adsT) : (player.sprinting ? 80 : 74);
745:   camera.fov = lerp(camera.fov, fov, Math.min(1, dt * 8));
746:   camera.updateProjectionMatrix();
747: 
748:   dom.reticle.classList.toggle('ads', weaponState.adsT > 0.45);
749:   dom.reticle.classList.toggle('wide', weaponState.reloading || player.sprinting);
750:   const spreadScale = 1 + (weaponState.adsT > 0.45 ? -0.25 : 0) + (player.sprinting ? 0.55 : 0) + weaponState.recoilKick * 4;
751:   dom.reticle.style.transform = `translate(-50%, -50%) scale(${spreadScale.toFixed(3)})`;
752: 
753:   if (weaponState.mouseDown && w.auto && !weaponState.reloading) attemptFire();
754: }
