796: function explodeBarrel(b) {
797:   if (b.exploded) return;
798:   b.exploded = true;
799:   b.mesh.visible = false;
800:   const index = world.worldShootables.indexOf(b.mesh);
801:   if (index >= 0) world.worldShootables.splice(index, 1);
802:   for (let i = world.colliders.length - 1; i >= 0; i--) {
803:     if (world.colliders[i].mesh === b.mesh) world.colliders.splice(i, 1);
804:   }
805:   const pos = b.position.clone().add(new THREE.Vector3(0, 0.8, 0));
806:   effects.explosion(pos, 8);
807:   audio.explosion();
808:   player.shake = Math.max(player.shake, 0.6);
809:   explosionDamage(pos, 8.5, 150, 0.42);
810: }
