812: function damageBarrel(mesh, damage) {
813:   const b = world.explosives.find(x => x.mesh === mesh && !x.exploded);
814:   if (!b) return;
815:   b.hp -= damage;
816:   effects.spark(b.position.clone().add(new THREE.Vector3(0, 0.7, 0)), 0xff6a3a, 8, 4, 0.35, 10);
817:   if (b.hp <= 0) {
818:     setTimeout(() => explodeBarrel(b), 80);
819:   }
820: }
