953: function drawRadar(t) {
954:   const ctx = dom.radar.getContext('2d');
955:   const w = dom.radar.width, h = dom.radar.height;
956:   const cx = w / 2, cy = h / 2;
957:   const r = w * 0.44;
958:   ctx.clearRect(0, 0, w, h);
959:   ctx.save();
960:   ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.clip();
961:   const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
962:   grad.addColorStop(0, 'rgba(30,73,80,0.32)');
963:   grad.addColorStop(1, 'rgba(4,10,12,0.2)');
964:   ctx.fillStyle = grad; ctx.fillRect(0, 0, w, h);
965:   ctx.strokeStyle = 'rgba(108,220,238,0.18)';
966:   ctx.lineWidth = 2;
967:   for (const rr of [r * 0.33, r * 0.66, r]) { ctx.beginPath(); ctx.arc(cx, cy, rr, 0, Math.PI * 2); ctx.stroke(); }
968:   ctx.beginPath(); ctx.moveTo(cx - r, cy); ctx.lineTo(cx + r, cy); ctx.moveTo(cx, cy - r); ctx.lineTo(cx, cy + r); ctx.stroke();
969:   // sweep
970:   const sweep = (t * 0.65) % (Math.PI * 2);
971:   ctx.strokeStyle = 'rgba(122,232,255,0.4)';
972:   ctx.lineWidth = 2;
973:   ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(sweep) * r, cy + Math.sin(sweep) * r); ctx.stroke();
974:   const scale = r / 48;
975:   for (const e of enemies) {
976:     if (e.dead || e.spawnT > 0.4) continue;
977:     const dx = e.root.position.x - player.pos.x;
978:     const dz = e.root.position.z - player.pos.z;
979:     const x = cx + dx * scale;
980:     const y = cy + dz * scale;
981:     if (Math.hypot(x - cx, y - cy) > r - 4) continue;
982:     const dist = Math.hypot(dx, dz);
983:     ctx.fillStyle = e.boss ? '#ff2035' : dist < 15 ? '#ff6a1a' : 'rgba(255,160,90,0.85)';
984:     ctx.beginPath(); ctx.arc(x, y, e.boss ? 8 : 5, 0, Math.PI * 2); ctx.fill();
985:     if (e.boss) { ctx.strokeStyle = 'rgba(255,40,60,0.7)'; ctx.lineWidth = 3; ctx.stroke(); }
986:   }
987:   // player arrow
988:   const fx = -Math.sin(player.yaw), fz = -Math.cos(player.yaw);
989:   ctx.save();
990:   ctx.translate(cx, cy);
991:   ctx.rotate(Math.atan2(fx, -fz));
992:   ctx.fillStyle = '#d9fbff';
993:   ctx.beginPath(); ctx.moveTo(0, -12); ctx.lineTo(-7, 8); ctx.lineTo(0, 4); ctx.lineTo(7, 8); ctx.closePath(); ctx.fill();
994:   ctx.restore();
995:   ctx.restore();
996:   // rim
997:   ctx.strokeStyle = 'rgba(122,232,255,0.3)';
998:   ctx.lineWidth = 2;
999:   ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
1000: }
