29:       uniform vec3 sunDir; uniform float time; varying vec3 vDir;
30:       float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
31:       void main() {
32:         float h = vDir.y;
33:         vec3 col = mix(horizonColor, midColor, smoothstep(0.0, 0.28, h));
