39:         float band = smoothstep(0.03, 0.0, abs(h - 0.01));
40:         col += vec3(0.24, 0.09, 0.03) * band * 0.4;
41:         gl_FragColor = vec4(col, 1.0);
42:       }
43:     `
44:   });
