146:     const col = this.particleGeo.attributes.color.array;
147:     for (let i = 0; i < this.maxParticles; i++) {
148:       const p = this.particles[i];
149:       if (!p.active) continue;
150:       p.life -= dt;
151:       if (p.life <= 0) {
152:         p.active = false;
153:         pos[i * 3 + 1] = -999;
