171:         t.mesh.material.dispose();
172:         this.tracers.splice(i, 1);
173:       } else {
174:         t.mesh.material.opacity = 0.95 * (t.life / t.max);
175:       }
176:     }
177: 
178:     for (let i = this.sprites.length - 1; i >= 0; i--) {
179:       const s = this.sprites[i];
180:       s.life -= dt;
181:       if (s.life <= 0) {
182:         this.scene.remove(s.sprite);
183:         s.sprite.material.dispose();
184:         this.sprites.splice(i, 1);
185:       } else {
186:         const f = s.life / s.max;
187:         s.sprite.material.opacity = f;
188:         const sc = s.startScale * (1 + (1 - f) * 0.6);
