203:       }
204:     }
205: 
206:     for (let i = this.casings.length - 1; i >= 0; i--) {
207:       const c = this.casings[i];
208:       c.life -= dt;
209:       if (c.life <= 0) {
210:         this.scene.remove(c.mesh);
211:         this.casings.splice(i, 1);
212:         continue;
213:       }
214:       c.vy -= 15 * dt;
215:       c.mesh.position.x += c.vx * dt;
216:       c.mesh.position.y += c.vy * dt;
217:       c.mesh.position.z += c.vz * dt;
218:       c.mesh.rotation.x += c.spin * dt;
219:       c.mesh.rotation.z += c.spin * 0.6 * dt;
