81: // Extrude a 2D side profile (points are [z, y]) across the weapon's X axis.
82: function profile(pts, thickness, material, parent, x = 0, bevel = 0.004) {
83:   const shape = new THREE.Shape();
84:   shape.moveTo(pts[0][0], pts[0][1]);
85:   for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
86:   shape.closePath();
87:   const geo = new THREE.ExtrudeGeometry(shape, {
88:     depth: thickness, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel,
89:     bevelSegments: 2, steps: 1, curveSegments: 8
90:   });
91:   geo.translate(0, 0, -thickness / 2);
92:   geo.rotateY(-Math.PI / 2);
93:   const mesh = new THREE.Mesh(geo, material);
94:   mesh.position.x = x;
95:   parent.add(mesh);
96:   return mesh;
97: }
